[
    {
        "title": "建立坐标系",
        "description": "在平面直角坐标系中标出交点 $A(2,3)$、$B(-1,-6)$ 及原点 $O$。",
        "bubbleText": "先把已知的两个交点放到图上，后面的函数参数都由它们确定。",
        "bubblePos": {
            "x": 260.0,
            "y": 70.0
        },
        "arrowTarget": {
            "x": 410.0,
            "y": 350.0
        }
    },
    {
        "title": "求反比例参数",
        "description": "由点 $A(2,3)$ 在反比例函数 $y=\\frac{m}{x}$ 的图象上，得 $3=\\frac{m}{2}$，所以 $m=6$，反比例函数为 $y=\\frac{6}{x}$。",
        "bubbleText": "把交点坐标代入反比例式，使用 $m=xy$，可得 $m=2×3=6$。",
        "bubblePos": {
            "x": 280.0,
            "y": 70.0
        },
        "arrowTarget": {
            "x": 540.0,
            "y": 284.0
        }
    },
    {
        "title": "求一次函数",
        "description": "将 $A(2,3)$、$B(-1,-6)$ 代入 $y=kx+b$，得 $3=2k+b$，$-6=-k+b$。两式相减得 $9=3k$，所以 $k=3$，代回得 $b=-3$，故一次函数为 $y=3x-3$。",
        "bubbleText": "两个交点都在同一条直线上，所以要把两个点分别代入，联立求出 $k$ 和 $b$。",
        "bubblePos": {
            "x": 220.0,
            "y": 70.0
        },
        "arrowTarget": {
            "x": 460.0,
            "y": 341.0
        }
    },
    {
        "title": "确定点C",
        "description": "一次函数与 $y$ 轴交点的横坐标为 $0$。令 $x=0$，得 $y=3×0-3=-3$，所以 $C(0,-3)$。",
        "bubbleText": "在 y 轴上的点横坐标一定是 $0$，代入直线解析式即可找到 C。",
        "bubblePos": {
            "x": 250.0,
            "y": 70.0
        },
        "arrowTarget": {
            "x": 410.0,
            "y": 416.0
        }
    },
    {
        "title": "列面积式",
        "description": "在三角形 $OBC$ 中，取 $OC=3$ 为底，点 $B$ 到 y 轴的距离为 $|-1|=1$，因此 $S_{△OBC}=\\frac{1}{2}×3×1=\\frac{3}{2}$。",
        "bubbleText": "用坐标看底和高最方便：$OC$ 长为 3，B 到 y 轴的水平距离为 1。",
        "bubblePos": {
            "x": 230.0,
            "y": 70.0
        },
        "arrowTarget": {
            "x": 388.0,
            "y": 416.0
        }
    },
    {
        "title": "检验作答",
        "description": "检验可知，底 $OC=3$，对应高为 $|x_B|=1$，重新计算仍得 $S_{△OBC}=\\frac{1}{2}×3×1=\\frac{3}{2}$。所以三角形 $OBC$ 的面积为 $\\frac{3}{2}$。",
        "bubbleText": "再用底乘高除以 2 检查一次，结果一致，因此答案正确。",
        "bubblePos": {
            "x": 235.0,
            "y": 70.0
        },
        "arrowTarget": {
            "x": 388.0,
            "y": 416.0
        }
    }
]
